entries[30480] = { ["name"] = "Zügel des feurigen Schlachtrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man das Ross von Attumen dem Jäger beschwört.\nBeschwört das Ross von Attumen dem Jäger oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"War eins der bösartigsten Pferde in den Stallungen von Karazhan.\"\nBeute von:\nAttumen der Jäger\nOrt:\nKarazhan" }
