entries[31354] = { ["name"] = "Rezept: Fläschchen der Titanen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der Titanen.\nBenötigt Klassische Alchemie\n(300)\nBenötigt Die Sha'tar\n- Ehrfürchtig\nVerkaufspreis:\nFläschchen der Titanen\nBenutzen: Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 228 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Gromsblut (7), Steinschuppenöl (3), Schwarzer Lotus , Kristallphiole" }
