entries[31356] = { ["name"] = "Rezept: Fläschchen der destillierten Weisheit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der destillierten Weisheit.\nBenötigt Klassische Alchemie\n(300)\nBenötigt Expedition des Cenarius\n- Ehrfürchtig\nVerkaufspreis:\nFläschchen der destillierten Weisheit\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 28 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (7), Eiskappe (3), Schwarzer Lotus , Kristallphiole" }
